"""Open or update the GitHub issue that tracks uncatalogued instruction wordings.

The loader's ``instruction_catalog`` report (``snapshot/instruction-forms.json``)
lists every instruction-like text in the Lovtidend archives that matches no
operation in ``instruction_catalog.json``.  Such a wording cannot be applied to
a provision, so it must be added to the catalogue by a pull request.  This
script turns a non-empty list into one open issue (created once, then kept
current with a comment whenever a form is seen for the first time) and never
fails the publication: the texts are still kept as ``unknown`` records.
"""
from __future__ import annotations

import argparse
import json
import os
import re
import sys
import urllib.error
import urllib.request

TITLE = "Ukjente endringsinstruksjoner i Lovtidend"
LABEL = "parser"
MARKER = "<!-- instruction-forms -->"
FOOTER = "\n\n---\n_Generated by [Claude Code](https://claude.ai/code)_"


def api(method: str, url: str, token: str, payload: dict | None = None) -> object:
    data = None if payload is None else json.dumps(payload).encode("utf-8")
    request = urllib.request.Request(url, data=data, method=method, headers={
        "Authorization": f"Bearer {token}",
        "Accept": "application/vnd.github+json",
        "X-GitHub-Api-Version": "2022-11-28",
        "Content-Type": "application/json",
    })
    with urllib.request.urlopen(request, timeout=60) as response:
        body = response.read()
    return json.loads(body) if body else None


def form_lines(forms: list[dict]) -> list[str]:
    lines = []
    for form in forms:
        examples = "; ".join(f"`{e['act']}`: {e['instruction'][:160]}" for e in form["examples"][:3])
        lines.append(f"- `{form['form']}` ({form['count']}) — {examples}")
    return lines


def issue_body(report: dict, run_url: str) -> str:
    lines = [
        MARKER,
        "The deploy run found instruction wordings in the Lovtidend archives that match no operation in "
        "`lovdata-loader/src/lovdata_loader/instruction_catalog.json`. They are kept as `unknown` records and "
        "cannot be attributed to a provision until the catalogue learns the wording.",
        "",
        "Add each wording to the catalogue (operation, pattern, example) in a pull request, or list it under "
        "`reviewed_non_instructions` if it is not an amendment instruction. This issue is updated by the deploy "
        "workflow whenever a wording is seen for the first time.",
        "",
        f"Catalogue version {report['catalog_version']}; {report['instructions']} instructions classified; run: {run_url}",
        "",
        "## Unknown forms",
        *form_lines(report["unknown_forms"]),
    ]
    return "\n".join(lines) + FOOTER


def known_forms(text: str) -> set[str]:
    return set(re.findall(r"^- `(.+?)` \(\d+\)", text or "", flags=re.M))


def find_issue(repository: str, token: str) -> dict | None:
    url = f"https://api.github.com/repos/{repository}/issues?state=open&labels={LABEL}&per_page=100"
    for issue in api("GET", url, token) or []:
        if issue.get("title") == TITLE and "pull_request" not in issue:
            return issue
    return None


def ensure_label(repository: str, token: str) -> None:
    try:
        api("GET", f"https://api.github.com/repos/{repository}/labels/{LABEL}", token)
    except urllib.error.HTTPError as error:
        if error.code != 404:
            raise
        api("POST", f"https://api.github.com/repos/{repository}/labels", token,
            {"name": LABEL, "color": "d93f0b", "description": "Parser must learn a new Lovtidend wording"})


def sync(report: dict, repository: str, token: str, run_url: str) -> dict:
    forms = report.get("unknown_forms", [])
    issue = find_issue(repository, token)
    if not forms:
        return {"action": "none", "issue": issue["html_url"] if issue else None}
    if issue is None:
        ensure_label(repository, token)
        created = api("POST", f"https://api.github.com/repos/{repository}/issues", token,
                      {"title": TITLE, "body": issue_body(report, run_url), "labels": [LABEL]})
        return {"action": "created", "issue": created["html_url"], "forms": len(forms)}
    seen = known_forms(issue.get("body", ""))
    comments = api("GET", issue["comments_url"] + "?per_page=100", token) or []
    for comment in comments:
        seen |= known_forms(comment.get("body", ""))
    new_forms = [f for f in forms if f["form"] not in seen]
    if not new_forms:
        return {"action": "unchanged", "issue": issue["html_url"], "forms": len(forms)}
    body = "\n".join([MARKER, f"New wordings first seen in {run_url}:", "", *form_lines(new_forms)]) + FOOTER
    api("POST", issue["comments_url"], token, {"body": body})
    return {"action": "commented", "issue": issue["html_url"], "forms": len(forms), "new_forms": len(new_forms)}


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("--report", required=True, help="instruction-forms.json written by the loader catalogue")
    parser.add_argument("--repository", required=True, help="owner/name")
    parser.add_argument("--run-url", default="", help="URL of the workflow run that produced the report")
    args = parser.parse_args(argv)
    token = os.environ.get("GITHUB_TOKEN") or os.environ.get("GH_TOKEN")
    if not token:
        print("GITHUB_TOKEN is not set", file=sys.stderr)
        return 2
    with open(args.report, encoding="utf-8") as stream:
        report = json.load(stream)
    result = sync(report, args.repository, token, args.run_url)
    print(json.dumps(result))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
